import{_ as l,a0 as t,w as d,s as o,I as i,x as a,a1 as n,A as p,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"三種在 Linux 上創建或擴展交換分區的簡單方法 | LCTT x X-CMD","titleTemplate":false,"description":"三種在 Linux 上創建或擴展交換分區的簡單方法 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"三種在 Linux 上創建或擴展交換分區的簡單方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"三種在 Linux 上創建或擴展交換分區的簡單方法 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170612 3 Easy Ways To Create Or Extend Swap Space In Linux","title":"三種在 Linux 上創建或擴展交換分區的簡單方法","tag":"201707","desc":""},"relativePath":"201707/20170612 3 Easy Ways To Create Or Extend Swap Space In Linux.md","filePath":"[post].md"}'),h={name:"201707/20170612 3 Easy Ways To Create Or Extend Swap Space In Linux.md"};function g(c,s,k,b,u,f){const e=t("Link");return d(),o("div",null,[s[18]||(s[18]=i("h1",{id:"三種在-linux-上創建或擴展交換分區的簡單方法",tabindex:"-1"},[a("三種在 Linux 上創建或擴展交換分區的簡單方法 "),i("a",{class:"header-anchor",href:"#三種在-linux-上創建或擴展交換分區的簡單方法","aria-label":"Permalink to “三種在 Linux 上創建或擴展交換分區的簡單方法”"},"​")],-1)),s[19]||(s[19]=i("p",null,"用户可以在任何 Linux\b 操作系統的安裝過程中或者是其它必要的時候創建交換空間。如果你在安裝 Linux 的時候忘記了創建或是你想要再增加交換分區的空間，你隨時都可以再創建或增加。",-1)),s[20]||(s[20]=i("p",null,"有時候在你安裝後搖升級 RAM 的時候需要增加一點交換分區的空間，比如你要將你的系統的 RAM 從 1GB 升級到 2GB 你，那麼你就不得不將你的交換分區空間也升級一下（從 2GB 到 4GB），這是因為它使用的容量是物理 RAM 的雙倍容量。（LCTT 譯註：其實這裏是個誤區，交換分區不一定非得是雙倍的物理內存容量，只是慣例如此。事實上，如果你的物理內存足夠的話，你完全可以不用交換分區——在這裏的情形下，或許你增加了物理內存，就沒必要增加交換分區大小了。）",-1)),s[21]||(s[21]=i("p",null,"\b\b交換空間是當物理內存（RAM 隨機存取存儲器）的用量已滿時，被保留用作虛擬內存的磁盤上的空間。 如果系統在 RAM 滿載時需要更多的內存資源，內存中的非活動頁面將被移動到交換空間，這樣可以幫助系統運行應用程序更多的時間，但不應\b該把它當做 RAM 的擴展。",-1)),s[22]||(s[22]=i("p",null,"建議你創建一個專用的交換分區，但是如果你沒有可用的分區，那麼可以使用交換文件，或交換分區和交換文件的組合。 交換空間通常建議用户至少 4 GB，用户也可以根據自己的要求和環境創建交換空間。",-1)),s[23]||(s[23]=i("p",null,"我發現大部分 VM 和 雲服務器都沒有交換分區，所以在這種情況下，我們可以使用以下三種方法創建，擴展或增加交換空間。",-1)),s[24]||(s[24]=i("h3",{id:"如何檢測當前交換分區大小",tabindex:"-1"},[a("如何檢測當前交換分區大小 "),i("a",{class:"header-anchor",href:"#如何檢測當前交換分區大小","aria-label":"Permalink to “如何檢測當前交換分區大小”"},"​")],-1)),i("p",null,[s[1]||(s[1]=a("通過 ",-1)),n(e,{href:"http://www.2daygeek.com/free-command-to-check-memory-usage-statistics-in-linux/"},{default:p(()=>[...s[0]||(s[0]=[a("free",-1)])]),_:1}),s[2]||(s[2]=a(" & ",-1)),s[3]||(s[3]=i("code",null,"swapon",-1)),s[4]||(s[4]=a(" 命令來檢測當前的交換分區空間的大小。",-1))]),s[25]||(s[25]=r(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ free -h</span></span>
<span class="line"><span>              total        used        free      shared  buff/cache   available</span></span>
<span class="line"><span>Mem:           2.0G        1.3G        139M         45M        483M        426M</span></span>
<span class="line"><span>Swap:          2.0G        655M        1.4G</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ swapon --show</span></span>
<span class="line"><span>NAME      TYPE      SIZE   USED PRIO</span></span>
<span class="line"><span>/dev/sda5 partition   2G 655.2M   -1</span></span></code></pre></div><p>上面的輸出顯示了\b當前的交換分區空間是 <code>2GB</code> 。</p><h3 id="方法-1-通過-fallocate-命令創建交換文件" tabindex="-1">方法 1 : 通過 fallocate 命令創建交換文件 <a class="header-anchor" href="#方法-1-通過-fallocate-命令創建交換文件" aria-label="Permalink to “方法 1 : 通過 fallocate 命令創建交換文件”">​</a></h3><p><code>fallocate</code> 程序是立即創建預分配大小的文件的最佳方法。</p><p>下面這個命令會創建一個 1GB 大小\b的 <code>/swapfile</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo fallocate -l 1G /swapfile</span></span></code></pre></div><p>檢查\b一下創建的文件的大小是否正確。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lh /swapfile</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 1.0G Jun  7 09:49 /swapfile</span></span></code></pre></div><p>將該文件的權限設置為 <code>600</code> 這樣只有 root 用户可以\b訪問這個文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod 600 /swapfile</span></span></code></pre></div><p>通過\b運行以下的命令來將此文件\b轉換為交換文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkswap /swapfile</span></span>
<span class="line"><span>Setting up swapspace version 1, size = 1024 MiB (1073737728 bytes)</span></span>
<span class="line"><span>no label, UUID=cda50e0e-41f3-49c7-af61-b8cb4a33a464</span></span></code></pre></div><p>通過運行以下的命令來使交換文件生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapon /swapfile</span></span></code></pre></div><p>將新創建的交換文件添加到 <code>fstab</code> 文件中，這樣交換分區空間\b的修改即使在重啓後也可以生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/swapfile  swap  swap  defaults  0 0</span></span></code></pre></div><p>檢查一下新創建的交換文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ swapon --show</span></span>
<span class="line"><span>NAME      TYPE       SIZE   USED PRIO</span></span>
<span class="line"><span>/dev/sda5 partition    2G 657.8M   -1</span></span>
<span class="line"><span>/swapfile file      1024M     0B   -2</span></span></code></pre></div><p>現在\b我可以看到一個新的  1GB 的 <code>/swapfile1</code> 文件了。重啓系統以使新的交換文件生效。</p><h3 id="方法-2-通過-dd-命令來創建交換文件" tabindex="-1">方法 2 : 通過 dd 命令來創建交換文件 <a class="header-anchor" href="#方法-2-通過-dd-命令來創建交換文件" aria-label="Permalink to “方法 2 : 通過 dd 命令來創建交換文件”">​</a></h3><p><code>dd</code> 命令是另一個實用程序，可以幫助我們立即創建預分配大小的文件。</p><p>以下 dd 命令將創建 1GB 的 <code>/swapfile1</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dd if=/dev/zero of=/swapfile1 bs=1G count=1</span></span>
<span class="line"><span>1+0 records in</span></span>
<span class="line"><span>1+0 records out</span></span>
<span class="line"><span>1073741824 bytes (1.1 GB, 1.0 GiB) copied, 16.6154 s, 64.6 MB/s</span></span></code></pre></div><p><strong>詳解：</strong></p><ul><li><code>if=/dev/zero</code> 是輸入文件，<code>/dev/zero</code> 是類 Unix 操作系統中的一個特殊文件，它提供從它讀取的儘可能多的空字符（ASCII NUL，0x00）。</li><li><code>of=/swapfile1</code> \b設置輸出文件。</li><li><code>bs=1G</code> 一次性讀寫的\b大小為 1GB</li><li><code>count=1</code> 僅複製一個輸入塊</li></ul><p>檢查\b一下創建的文件的大小是否正確。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -lh /swapfile1</span></span>
<span class="line"><span>-rw-r--r-- 1 root root 1.0G Jun  7 09:58 /swapfile1</span></span></code></pre></div><p>將該文件的權限設置為 <code>600</code> 這樣只有 root 用户可以\b訪問這個文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod 600 /swapfile1</span></span></code></pre></div><p>通過\b運行以下的命令來將此文件\b轉換為交換文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkswap /swapfile1</span></span>
<span class="line"><span>Setting up swapspace version 1, size = 1024 MiB (1073737728 bytes)</span></span>
<span class="line"><span>no label, UUID=96def6d7-b2da-4954-aa72-aa32316ec993</span></span></code></pre></div><p>通過運行以下的命令來使交換文件生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapon /swapfile1</span></span></code></pre></div><p>將新創建的交換文件添加到 <code>fstab</code> 文件中，這樣交換分區空間\b的修改即使在重啓後也可以生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/swapfile1  swap  swap  defaults  0 0</span></span></code></pre></div><p>檢查新創建的交換文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ swapon --show</span></span>
<span class="line"><span>NAME       TYPE       SIZE USED PRIO</span></span>
<span class="line"><span>/dev/sda5  partition    2G 1.3G   -1</span></span>
<span class="line"><span>/swapfile  file      1024M   0B   -2</span></span>
<span class="line"><span>/swapfile1 file      1024M   0B   -3</span></span></code></pre></div><p>現在\b我可以看到一個新的  1GB 的 <code>/swapfile1</code> 了。重啓系統以使新的交換文件生效。</p><h3 id="方法-3-通過硬盤分區來創建交換文件" tabindex="-1">方法 3 : 通過硬盤分區來創建\b交換文件 <a class="header-anchor" href="#方法-3-通過硬盤分區來創建交換文件" aria-label="Permalink to “方法 3 : 通過硬盤分區來創建\b交換文件”">​</a></h3><p>我們也推薦使用通過硬盤分區的方式來創建交換分區。</p><p>如果你已經在你的另一個硬盤上通過 <code>fdisk</code> 命令創建了一個新的分區，假設我們已經創建了一個叫做 <code>/dev/sda4</code> 的分區。</p><p>使用 <code>mkswap</code> 命令來將這個分區轉換成交換\b分區。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkswap /dev/sda4</span></span></code></pre></div><p>通過\b運行以下命令來使交換文件生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo swapon /dev/sda4</span></span></code></pre></div><p>把新增的交換文件添加到 <code>fstab</code> 文件中，這樣即使是重啓了系統交換分區的\b修改也能生效。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/fstab</span></span>
<span class="line"><span></span></span>
<span class="line"><span>/dev/sda4  swap  swap  defaults  0 0</span></span></code></pre></div><p>檢查新創建的交換文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ swapon --show</span></span>
<span class="line"><span>NAME       TYPE       SIZE USED PRIO</span></span>
<span class="line"><span>/dev/sda5  partition    2G 1.3G   -1</span></span>
<span class="line"><span>/swapfile  file      1024M   0B   -2</span></span>
<span class="line"><span>/swapfile1 file      1024M   0B   -3</span></span>
<span class="line"><span>/dev/sda4  partition    1G   0B   -4</span></span></code></pre></div><p>我可以看到新的交換分區 1GB 的 <code>/dev/sda4</code>。重啓系統就可以使用新的交換分區了。</p><hr>`,51)),i("p",null,[s[6]||(s[6]=a("via: ",-1)),n(e,{href:"http://www.2daygeek.com/add-extend-increase-swap-space-memory-file-partition-linux/"},{default:p(()=>[...s[5]||(s[5]=[a("http://www.2daygeek.com/add-extend-increase-swap-space-memory-file-partition-linux/",-1)])]),_:1})]),i("p",null,[s[10]||(s[10]=a("作者：",-1)),n(e,{href:"http://www.2daygeek.com/author/2daygeek/"},{default:p(()=>[...s[7]||(s[7]=[a("2DAYGEEK",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),n(e,{href:"https://github.com/chenxinlong"},{default:p(()=>[...s[8]||(s[8]=[a("chenxinlong",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:p(()=>[...s[9]||(s[9]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:p(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const m=l(h,[["render",g]]);export{x as __pageData,m as default};
